 import React, { useState, useEffect } from 'react'
import { Joyride } from 'react-joyride'
import { useAuth } from '../contexts/AuthContext'

export default function OnboardingTour() {
    const { user } = useAuth()
    const [run, setRun] = useState(false)

    useEffect(() => {
        const hasSeenTour = localStorage.getItem(`predictfc_tour_${user?.id}`)
        
        if (user && !hasSeenTour) {
            const timer = setTimeout(() => {
                setRun(true)
            }, 1000)
            return () => clearTimeout(timer)
        }
    }, [user])

    const handleTourFinish = () => {
        localStorage.setItem(`predictfc_tour_${user?.id}`, 'true')
        setRun(false)
    }

    const steps = [
        // Step 1: Welcome
        {
            target: 'body',
            content: (
                <div className="text-center max-w-xs">
                    <h3 className="font-bold text-lg mb-2 text-gray-900">👋 Welcome to PredictFC!</h3>
                    <p className="text-sm text-gray-600">Let's take a quick tour so you know exactly where everything is.</p>
                </div>
            ),
            placement: 'center',
            disableBeacon: true,
        },
        
        // Step 2: Feed
        {
            target: '.tour-feed',
            content: '📰 This is your Feed. See posts, predictions, and updates from the community.',
            placement: 'bottom',
            floaterProps: { disableAnimation: false },
            spotlightClicks: true,
        },
        
        // Step 3: Matches
        {
            target: '.tour-matches',
            content: '⚽ View all upcoming matches and make your predictions here.',
            placement: 'bottom',
            floaterProps: { disableAnimation: false },
            spotlightClicks: true,
        },
        
        // Step 4: Community
        {
            target: '.tour-community',
            content: '🏛️ Join or create private communities to predict with friends and fans.',
            placement: 'bottom',
            floaterProps: { disableAnimation: false },
            spotlightClicks: true,
        },
        
        // Step 5: Slip
        {
            target: '.tour-slip',
            content: '📋 Build a multi-match bet slip and share your prediction strategy.',
            placement: 'bottom',
            floaterProps: { disableAnimation: false },
            spotlightClicks: true,
        },
        
        // Step 6: Profile (BOTTOM NAV)
        {
            target: '.tour-profile-bottom',
            content: '👤 View your personal stats, points, predictions, and manage your profile here.',
            placement: 'top',
            floaterProps: { disableAnimation: false },
            spotlightClicks: true,
        },
        
        // Step 7: Notifications (BOTTOM NAV)
        {
            target: '.tour-notifications-bottom',
            content: '🔔 See who liked your posts, commented, or followed you.',
            placement: 'top',
            floaterProps: { disableAnimation: false },
            spotlightClicks: true,
        },
        
        // Step 8: Inbox / Messages (BOTTOM NAV)
        {
            target: '.tour-inbox-bottom',
            content: '💬 Chat directly with other users in your private messages.',
            placement: 'top',
            floaterProps: { disableAnimation: false },
            spotlightClicks: true,
        },
        
        // Step 9: Finished
        {
            target: 'body',
            content: (
                <div className="text-center max-w-xs">
                    <h3 className="font-bold text-lg mb-2 text-gray-900">🎉 You're ready!</h3>
                    <p className="text-sm text-gray-600">Start predicting, earning points, and climbing the leaderboard. Have fun!</p>
                </div>
            ),
            placement: 'center',
        },
    ]

    return (
        <Joyride
            steps={steps}
            run={run}
            continuous={true}
            showProgress={true}
            showSkipButton={true}
            hideCloseButton={true}
            disableOverlayClose={true}
            spotlightPadding={10}
            floaterProps={{
                hideArrow: false,
                disableAnimation: false,
            }}
            styles={{
                options: {
                    primaryColor: '#1a1a1a',
                    backgroundColor: '#ffffff',
                    textColor: '#1a1a1a',
                    arrowColor: '#ffffff',
                },
                buttonNext: {
                    backgroundColor: '#1a1a1a',
                    color: '#ffffff',
                    padding: '10px 24px',
                    borderRadius: '8px',
                    fontWeight: '600',
                    fontSize: '14px',
                    cursor: 'pointer',
                },
                buttonBack: {
                    color: '#666666',
                    padding: '10px 16px',
                    fontSize: '14px',
                    cursor: 'pointer',
                },
                buttonSkip: {
                    color: '#999999',
                    padding: '10px 16px',
                    fontSize: '14px',
                    cursor: 'pointer',
                },
                spotlight: {
                    backgroundColor: 'rgba(0, 0, 0, 0.6)',
                },
            }}
            callback={(data) => {
                if (data.status === 'finished' || data.status === 'skipped') {
                    handleTourFinish()
                }
            }}
        />
    )
}
